/**  `<root>/state/forgebox.sock`, mode 0600 (Linux, macOS). */
"unix_socket" | 
/**  `wss://host:7788`, mTLS or token (remote mode, M6). */
"web_socket_tls" | 
/**  SSH tunnel to a remote unix socket (remote mode, v1.x). */
"ssh_tunnel" | 
/**  In-process duplex (tests, embedding). */
"in_memory";

